#ifndef REGISTER_HPP
#define REGISTER_HPP

template <typename T>
class Register {
public:
    T prev;
    T next;

    Register();
    Register(T d);
    T read() const;
    T current() const;
    void write(const T &t);
    void tick();
    void stall(bool stall);
    operator T() const;
    Register& operator=(T next);

private:
    bool _stall;
};

template <typename T>
Register<T>::Register()
    : prev(0), next(0), _stall(false) {}

template <typename T>
Register<T>::Register(T d)
    : prev(d), next(d), _stall(false) {}

template <typename T>
T Register<T>::read() const {
    return prev;
}

template <typename T>
T Register<T>::current() const {
    return next;
}

template <typename T>
void Register<T>::write(const T &t) {
    next = t;
}

template <typename T>
void Register<T>::tick() {
    if (!_stall) {
        prev = next;
    }
}

template <typename T>
void Register<T>::stall(bool stall) {
    _stall = stall;
}

template <typename T>
Register<T>::operator T() const {
    return read();
}

template <typename T>
Register<T>& Register<T>::operator=(T next) {
    write(next);
    return *this;
}

#endif // REGISTER_HPP
